// A3 unit tests for the l10n validator (kielbasa-2), tightened by the a-gate
// node: all 56 locales are real translations, so the stub-skip is removed and
// the full-table assertion runs unconditionally. The self-test runs the check
// logic against synthetic good/bad tables; the full pass runs it against the
// real 56-locale table plus the evals-tree canary grep.
//
// The l10n task JSONs + fixture dirs are NOT committed -- they are generated by
// `bun run gen-fixtures` (evals/tools/prepare.ts). The tree-scan half of the full pass
// only makes sense when those generated artifacts are on disk, so it skips when
// they're absent (a fresh clone that hasn't run gen-fixtures yet). The table checks
// (validateTable) and self-test never depend on generated files and always run.
import { describe, expect, test } from "bun:test";
import { existsSync } from "node:fs";
import { join } from "node:path";
import {
  DEFAULT_TABLE_RULES,
  checkTreeFindings,
  makeBatchMembership,
  runSelfTest,
  scanEvalsTree,
  validateTable,
} from "../../evals/tools/l10n-validate.ts";
import { locales } from "../../evals/tools/l10n-data.ts";

describe("l10n-validate self-test", () => {
  test("each check fires on its synthetic bad case; synthetic good table passes", () => {
    expect(runSelfTest()).toEqual([]);
  });
});

// The generated l10n artifacts (batch task JSONs + fixture dirs) must be present
// for the evals-tree canary grep to have anything to attribute. Absent on a fresh
// clone until `bun run gen-fixtures` runs -- then skip rather than false-fail.
const TASKS_DIR = join(import.meta.dir, "..", "..", "evals", "series", "kielbasa-2", "tasks");
const HAVE_L10N_FIXTURES = existsSync(join(TASKS_DIR, "fixture-l10n-batch-a"));
const fullSuite = HAVE_L10N_FIXTURES ? describe : describe.skip;

fullSuite("l10n full table", () => {
  test("all 56 locales pass the validator and canaries are evals-tree unique", async () => {
    const errors = validateTable(locales, DEFAULT_TABLE_RULES);
    // Batch membership via the shared helper (same slicing gen-l10n.ts uses): a
    // canary is allowed in a combined batch fixture/task only if its owner locale
    // is actually in that batch.
    const membership = makeBatchMembership(locales);
    const findings = scanEvalsTree(join(import.meta.dir, "..", "..", "evals"), locales);
    errors.push(...checkTreeFindings(locales, findings, membership));
    expect({ count: errors.length, first20: errors.slice(0, 20) }).toEqual({ count: 0, first20: [] });
  });
});
